import subprocess,re,sys
patterns=[
 ('postgres_url', re.compile(r'postgres://[^\s\"\']+')),
 ('telegram_token', re.compile(r'\b\d{8,10}:[A-Za-z0-9_-]{35,}\b')),
 ('bot_token_env', re.compile(r'\b(?:PROD_BOT_TOKEN|TEST_BOT_TOKEN|BOT_TOKEN)\s*=\s*[^\s#]+')),
 ('database_url_env', re.compile(r'\bDATABASE_URL\s*=\s*[^\s#]+')),
]
commits=subprocess.check_output(['git','rev-list','--all'], text=True).splitlines()
seen=set(); findings=[]
for c in commits:
    try:
        files=subprocess.check_output(['git','ls-tree','-r','--name-only',c], text=True, stderr=subprocess.DEVNULL).splitlines()
    except subprocess.CalledProcessError:
        continue
    for path in files:
        if path.startswith('.git/') or path.endswith('go.sum'):
            continue
        try:
            data=subprocess.check_output(['git','show',f'{c}:{path}'], stderr=subprocess.DEVNULL)
        except subprocess.CalledProcessError:
            continue
        if b'\0' in data[:4096]:
            continue
        text=data.decode('utf-8','ignore')
        for i,line in enumerate(text.splitlines(),1):
            for name,rx in patterns:
                if rx.search(line):
                    key=(name,path,line.strip())
                    if key in seen: continue
                    seen.add(key)
                    red=rx.sub(lambda m: m.group(0).split('=')[0]+'=<redacted>' if '=' in m.group(0) else '<redacted>', line.strip())
                    findings.append((name,c[:7],path,i,red[:180]))
                    if len(findings)>=100:
                        break
            if len(findings)>=100: break
        if len(findings)>=100: break
    if len(findings)>=100: break
for f in findings:
    print('%s %s %s:%s %s' % f)
print('findings:',len(findings), file=sys.stderr)
